const MAX_URLS = 12;
const URL_REGEX = /https?:\/\/[^\s<>"']+/gi;

function normalizeUrl(value = "") {
  const cleaned = String(value || "")
    .trim()
    .replace(/[\]),.;]+$/g, "");

  try {
    const parsed = new URL(cleaned);
    if (!["http:", "https:"].includes(parsed.protocol)) return "";
    return parsed.href;
  } catch {
    return "";
  }
}

function extractUrls(...texts) {
  const urls = [];
  const seen = new Set();

  for (const text of texts) {
    const matches = String(text || "").match(URL_REGEX) || [];
    for (const match of matches) {
      const url = normalizeUrl(match);
      if (!url || seen.has(url)) continue;
      seen.add(url);
      urls.push(url);
      if (urls.length >= MAX_URLS) return urls;
    }
  }

  return urls;
}

function getTypeHint(text = "") {
  const first = String(text || "").trim().split(/\s+/)[0]?.toLowerCase() || "";
  if (["audio", "aud", "musica", "música", "mp3"].includes(first)) return "audio";
  if (["video", "vid", "mp4"].includes(first)) return "video";
  if (["imagen", "image", "img", "foto", "picture"].includes(first)) return "image";
  return "";
}

function extType(url = "") {
  try {
    const parsed = new URL(url);
    const path = decodeURIComponent(parsed.pathname || "").toLowerCase();
    if (/\.(mp3|wav|ogg|opus|m4a|aac|flac)(?:$)/i.test(path)) return "audio";
    if (/\.(mp4|webm|mov|m4v|avi|mkv|3gp)(?:$)/i.test(path)) return "video";
    if (/\.(jpg|jpeg|png|webp|gif|bmp|avif)(?:$)/i.test(path)) return "image";
  } catch {}
  return "";
}

function guessMediaType(url = "", hint = "") {
  if (hint) return hint;

  const byExt = extType(url);
  if (byExt) return byExt;

  try {
    const parsed = new URL(url);
    const full = parsed.href.toLowerCase();
    if (/(audio|mp3|sound|music|song)/i.test(full)) return "audio";
    if (/(video|mp4|reel|short|movie)/i.test(full)) return "video";
    if (/(image|img|photo|foto|picture|avatar)/i.test(full)) return "image";
  } catch {}

  return "audio";
}

const DOWNLOAD_TIMEOUT_MS = 45000;
const SNIFF_UA =
  "Mozilla/5.0 (Linux; Android 13; SM-S901B) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36";
// El visor de WhatsApp no descarga URLs remotas: el medio debe ir incrustado
// en base64 dentro del HTML. Pero WhatsApp rechaza/cuelga mensajes muy grandes
// (~2MB ya falla; ~300KB llega bien), así que:
//  - se incrustan archivos de hasta 750KB sin tocar (calidad original),
//  - los más grandes se comprimen a MÁXIMA CALIDAD (~1.25MB, perfil High,
//    ~337kbps a 360p = nitidez normal) y se intenta enviar;
//  - si WhatsApp no acepta ese tamaño, el plan B recomprime a ~620KB
//    (versión que se sabe entregable) y reintenta; luego queda URL directa.
const DOWNLOAD_LIMIT = 150 * 1024 * 1024; // máx descarga (para luego comprimir)
const DIRECT_EMBED_LIMIT = 750 * 1024;
const IMAGE_EMBED_LIMIT = 220 * 1024; // las imágenes van compactas (dejan espacio al audio fijo) // raw máx para incrustar sin comprimir (calidad intacta)
const SAFE_EMBED_TARGET = 620 * 1024; // objetivo del plan B (versión entregable comprobada)
const COMPRESS_TARGET = SAFE_EMBED_TARGET; // objetivo por defecto al comprimir
const COMPRESS_HARD_CAP = 900 * 1024; // techo absoluto del archivo procesado
const EMBED_TARGET_HQ = 860 * 1024; // objetivo HQ en crudo (~1.17MB de payload)
const EMBED_TOTAL_BUDGET = 1250 * 1024; // presupuesto HQ total en crudo (reparto)
const HQ_PAYLOAD_KB = 1300; // techo del payload del 1er envío en KB (validación)
const RELAY_TIMEOUT_MS = 12000; // fail-fast: si se cuelga, al plan B en 12s


// 🎵 Audio fijo que siempre llevan las tarjetas de IMAGEN (80s con fade,
// mp3 48kbps mono). Va horneado en el plugin para no depender de la URL.
const FIXED_IMAGE_AUDIO_URI = "data:audio/mpeg;base64,";

const MIME_BY_EXT = {
  mp3: "audio/mpeg", wav: "audio/wav", ogg: "audio/ogg", opus: "audio/ogg",
  m4a: "audio/mp4", aac: "audio/aac", flac: "audio/flac",
  mp4: "video/mp4", webm: "video/webm", mov: "video/quicktime", m4v: "video/x-m4v",
  avi: "video/x-msvideo", mkv: "video/x-matroska", "3gp": "video/3gpp",
  jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png", webp: "image/webp",
  gif: "image/gif", bmp: "image/bmp", avif: "image/avif",
};

function extOf(url = "") {
  try {
    const path = decodeURIComponent(new URL(url).pathname || "");
    const match = path.match(/\.([a-z0-9]+)$/i);
    return match ? match[1].toLowerCase() : "";
  } catch {
    return "";
  }
}

function mimeFor(url = "", headerCt = "", type = "") {
  const byExt = MIME_BY_EXT[extOf(url)];
  if (byExt) return byExt;
  const ct = String(headerCt || "").toLowerCase().split(";")[0].trim();
  if (/^(video|audio|image)\//.test(ct)) return ct;
  return type === "video" ? "video/mp4" : type === "image" ? "image/jpeg" : "audio/mpeg";
}

function typeFromContentType(ct = "") {
  const t = String(ct || "").toLowerCase().split(";")[0].trim();
  if (!t) return "";
  if (t.startsWith("video/") || t.includes("mp4") || t.includes("webm") || t.includes("matroska")) return "video";
  if (t.startsWith("image/")) return "image";
  if (t.startsWith("audio/") || t.includes("ogg") || t.includes("mpeg") || t.includes("wav") || t.includes("opus") || t.includes("aac") || t.includes("flac")) return "audio";
  return "";
}

function typeFromBytes(buf) {
  if (!buf || buf.length < 12) return "";
  const u = Buffer.from(buf.subarray(0, 64));
  const ascii = u.toString("latin1");

  if (ascii.slice(4, 8) === "ftyp") return "video"; // MP4 / M4V / MOV
  if (u[0] === 0x1a && u[1] === 0x45 && u[2] === 0xdf && u[3] === 0xa3) return "video"; // WebM / MKV
  if (ascii.slice(0, 4) === "RIFF") {
    const kind = ascii.slice(8, 12);
    if (kind === "AVI ") return "video";
    if (kind === "WAVE") return "audio";
    if (kind === "WEBP") return "image";
    return "";
  }
  if (ascii.slice(0, 4) === "OggS") return "audio";
  if (ascii.slice(0, 4) === "fLaC") return "audio";
  if (ascii.slice(0, 3) === "ID3") return "audio";
  if (u[0] === 0xff && u[1] === 0xd8) return "image"; // JPEG
  if (u[0] === 0x89 && ascii.slice(1, 4) === "PNG") return "image";
  if (ascii.slice(0, 3) === "GIF") return "image";
  if (u[0] === 0xff && (u[1] & 0xe0) === 0xe0) return "audio"; // MPEG audio sync
  return "";
}

async function downloadMedia(url, maxBytes = DOWNLOAD_LIMIT) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), DOWNLOAD_TIMEOUT_MS);
  try {
    const res = await fetch(url, {
      redirect: "follow",
      signal: controller.signal,
      headers: { "user-agent": SNIFF_UA, accept: "*/*" },
    });
    const contentType = (res.headers.get("content-type") || "").split(";")[0].trim();
    if (!res.ok && res.status !== 206) {
      try {
        await res.body?.cancel();
      } catch {}
      return { ok: false, status: res.status, contentType };
    }

    const len = Number(res.headers.get("content-length") || 0);
    if (len && len > maxBytes) {
      try {
        await res.body?.cancel();
      } catch {}
      return { ok: true, status: res.status, contentType, tooBig: true };
    }

    const chunks = [];
    let total = 0;
    const reader = res.body.getReader();
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.length;
      if (total > maxBytes) {
        try {
          reader.cancel();
        } catch {}
        return { ok: true, status: res.status, contentType, tooBig: true };
      }
      chunks.push(Buffer.from(value));
    }
    return { ok: true, status: res.status, contentType, buffer: Buffer.concat(chunks) };
  } finally {
    clearTimeout(timer);
  }
}

// ── Compresión (para que cualquier archivo quepa en el mensaje) ──────────
let ffmpegCache;
let ffmpegPathCache;
let sharpCache;

async function loadFfmpeg() {
  if (ffmpegCache !== undefined) return ffmpegCache;
  try {
    const [{ default: ffmpeg }, installerMod] = await Promise.all([
      import("fluent-ffmpeg"),
      import("@ffmpeg-installer/ffmpeg"),
    ]);
    const installer = installerMod.default || installerMod;
    ffmpegPathCache = installer.path || null;
    ffmpeg.setFfmpegPath(ffmpegPathCache);
    ffmpegCache = ffmpeg;
  } catch {
    ffmpegCache = null;
  }
  return ffmpegCache;
}

async function loadSharp() {
  if (sharpCache !== undefined) return sharpCache;
  try {
    const mod = await import("sharp");
    sharpCache = mod.default || mod;
  } catch {
    sharpCache = null;
  }
  return sharpCache;
}

const FFMPEG_STEP_TIMEOUT_MS = 120000; // máx por pasada de ffmpeg

function runFfmpeg(ffmpeg, inputPath, outputPath, args, timeoutMs = FFMPEG_STEP_TIMEOUT_MS) {
  return new Promise((resolve, reject) => {
    const cmd = ffmpeg(inputPath)
      .outputOptions(args)
      .output(outputPath)
      .on("error", (e) => {
        clearTimeout(timer);
        reject(e);
      })
      .on("end", () => {
        clearTimeout(timer);
        resolve();
      });
    const timer = setTimeout(() => {
      try {
        cmd.kill("SIGKILL");
      } catch {}
      reject(new Error("ffmpeg timeout"));
    }, timeoutMs);
    cmd.run();
  });
}

const VIDEO_LADDER = [
  { h: 480, crf: 27, ab: "64k" },
  { h: 360, crf: 31, ab: "48k" },
  { h: 256, crf: 34, ab: "24k" },
  { h: 180, crf: 36, ab: null }, // último recurso: sin audio
];

// Duración del video (segundos) leyendo el stderr de `ffmpeg -i`
function probeDurationSec(file) {
  return new Promise((resolve) => {
    if (!ffmpegPathCache) return resolve(0);
    execFile(
      ffmpegPathCache,
      ["-i", file],
      { timeout: 15000, maxBuffer: 2 * 1024 * 1024 },
      (_err, _stdout, stderr) => {
        const match = /Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)/.exec(String(stderr || ""));
        resolve(
          match
            ? Number(match[1]) * 3600 + Number(match[2]) * 60 + Number(match[3])
            : 0,
        );
      },
    );
  });
}

// Codificación a 2 pasadas: calcula el bitrate exacto para clavar el tamaño
// objetivo con la mejor calidad posible (resolución según bitrate disponible).
async function twoPassToSize(ffmpeg, inPath, outPath, passLog, targetBytes, dur) {
  const audioKbps = 32;
  const overheadKbps = 12; // contenedor + cabeceras
  const vk = Math.floor((targetBytes * 8) / 1000 / dur) - audioKbps - overheadKbps;
  if (vk < 40) return null; // video demasiado largo para este tamaño

  const h = vk >= 350 ? 480 : vk >= 170 ? 360 : vk >= 90 ? 240 : 180;
  // videos cortos: preset de mejor calidad (más calidad con los mismos bits)
  const preset = dur <= 90 ? "medium" : "veryfast";
  const args = (pass) => [
    "-c:v", "libx264", "-preset", preset, "-b:v", `${vk}k`,
    "-maxrate", `${Math.floor(vk * 2.5)}k`, "-bufsize", `${vk * 5}k`,
    "-profile:v", "high", "-level", "4.0", "-pix_fmt", "yuv420p",
    "-vf", `scale=-2:'min(ih,${h})',unsharp=5:5:0.6:5:5:0.0`,
    "-c:a", "aac", "-b:a", `${audioKbps}k`, "-ac", "1",
    "-pass", String(pass), "-passlogfile", passLog,
    "-movflags", "+faststart",
  ];
  await runFfmpeg(ffmpeg, inPath, outPath, args(1));
  await runFfmpeg(ffmpeg, inPath, outPath, args(2));
  const out = fs.readFileSync(outPath);
  return out.length <= COMPRESS_HARD_CAP ? out : null;
}

async function compressVideo(buffer, targetBytes) {
  const ffmpeg = await loadFfmpeg();
  if (!ffmpeg) return null;
  const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const tmpIn = path.join(os.tmpdir(), `p22-${id}-in`);
  const tmpOut = path.join(os.tmpdir(), `p22-${id}-out.mp4`);
  const passLog = path.join(os.tmpdir(), `p22-${id}-pass`);
  fs.writeFileSync(tmpIn, buffer);
  try {
    // 1ª opción: 2 pasadas con bitrate calculado (mejor calidad al tamaño dado)
    const dur = await probeDurationSec(tmpIn);
    if (dur > 900) return null; // +15 min: mejor entregar la URL directa
    if (dur > 0.5) {
      const out = await twoPassToSize(ffmpeg, tmpIn, tmpOut, passLog, targetBytes, dur);
      if (out) return out;
    }
    // Respaldo: escalera CRF descendente
    let best = null;
    const accept = Math.min(COMPRESS_HARD_CAP, Math.max(targetBytes * 1.6, 400 * 1024));
    for (const step of VIDEO_LADDER) {
      const audioArgs = step.ab
        ? ["-c:a", "aac", "-b:a", step.ab, "-ac", "1"]
        : ["-an"];
      await runFfmpeg(ffmpeg, tmpIn, tmpOut, [
        "-c:v", "libx264", "-preset", "ultrafast", "-crf", String(step.crf),
        "-profile:v", "high", "-level", "4.0", "-pix_fmt", "yuv420p",
        "-vf", `scale=-2:'min(ih,${step.h})',unsharp=5:5:0.6:5:5:0.0`,
        ...audioArgs,
        "-movflags", "+faststart",
      ]);
      const out = fs.readFileSync(tmpOut);
      if (!best || out.length < best.length) best = out;
      if (out.length <= targetBytes) return out;
    }
    return best && best.length <= accept ? best : null;
  } catch {
    return null;
  } finally {
    for (const f of [
      tmpIn,
      tmpOut,
      `${passLog}-0.log`,
      `${passLog}-0.log.mbtree`,
      `${passLog}-0.log.temp`,
    ]) {
      try {
        fs.unlinkSync(f);
      } catch {}
    }
  }
}

const AUDIO_LADDER = [
  { ab: "64k" },
  { ab: "40k" },
  { ab: "24k" },
];

async function compressAudio(buffer, targetBytes) {
  const ffmpeg = await loadFfmpeg();
  if (!ffmpeg) return null;
  const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const tmpIn = path.join(os.tmpdir(), `p22-${id}-in`);
  const tmpOut = path.join(os.tmpdir(), `p22-${id}-out.mp3`);
  fs.writeFileSync(tmpIn, buffer);
  try {
    let best = null;
    for (const step of AUDIO_LADDER) {
      await runFfmpeg(ffmpeg, tmpIn, tmpOut, [
        "-vn", "-c:a", "libmp3lame", "-b:a", step.ab, "-ac", "1", "-ar", "22050",
      ]);
      const out = fs.readFileSync(tmpOut);
      if (!best || out.length < best.length) best = out;
      if (out.length <= targetBytes) return out;
    }
    return best.length <= COMPRESS_HARD_CAP ? best : null;
  } catch {
    return null;
  } finally {
    try {
      fs.unlinkSync(tmpIn);
    } catch {}
    try {
      fs.unlinkSync(tmpOut);
    } catch {}
  }
}

async function compressImage(buffer, targetBytes) {
  const sharp = await loadSharp();
  if (!sharp) return null;
  try {
    const attempts = [
      (img) => img.resize({ width: 800 }).jpeg({ quality: 78 }),
      (img) => img.resize({ width: 560 }).jpeg({ quality: 70 }),
      (img) => img.resize({ width: 380 }).jpeg({ quality: 62 }),
      (img) => img.resize({ width: 300 }).jpeg({ quality: 55 }),
      (img) => img.resize({ width: 240 }).jpeg({ quality: 50 }),
    ];
    let best = null;
    for (const make of attempts) {
      const out = await make(sharp(buffer)).toBuffer();
      if (!best || out.length < best.length) best = out;
      if (out.length <= targetBytes) return out;
    }
    return best.length <= COMPRESS_HARD_CAP ? best : null;
  } catch {
    return null;
  }
}

async function compressMedia(buffer, type, targetBytes = COMPRESS_TARGET) {
  if (type === "video") return compressVideo(buffer, targetBytes);
  if (type === "audio") return compressAudio(buffer, targetBytes);
  if (type === "image") return compressImage(buffer, targetBytes);
  return null;
}

function dataUriFor(item, buffer) {
  const mime = item.compressed
    ? item.type === "video"
      ? "video/mp4"
      : item.type === "image"
        ? "image/jpeg"
        : "audio/mpeg"
    : mimeFor(item.url, item.ct, item.type);
  return `data:${mime};base64,${buffer.toString("base64")}`;
}

// ── yt-dlp: videos de hasta 1080p desde cualquier sitio soportado ────────
const YT_DLP_TIMEOUT_MS = 180000; // 3 min máx por video
let ytDlpCache; // binario resuelto una sola vez

async function resolveYtDlp() {
  if (ytDlpCache !== undefined) return ytDlpCache;
  const candidates = [
    "yt-dlp",
    path.join(process.cwd(), "yt-dlp"),
    path.join(process.cwd(), "yt-dlp_linux"),
    "yt-dlp_linux",
    "youtube-dl",
  ];
  for (const cmd of candidates) {
    const ok = await new Promise((resolve) => {
      execFile(cmd, ["--version"], { timeout: 10000 }, (err) => resolve(!err));
    });
    if (ok) {
      ytDlpCache = cmd;
      return cmd;
    }
  }
  // no cachea el fallo: si instalan yt-dlp después, lo detecta solo
  return null;
}

// Descarga el video con yt-dlp (máx 1080p) y devuelve el buffer en mp4.
// Devuelve null si yt-dlp no está instalado o falla (se usa el respaldo).
async function tryYtDlp(url) {
  const cmd = await resolveYtDlp();
  if (!cmd) return null;
  const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const base = path.join(os.tmpdir(), `p22-${id}-yt`);
  const cleanup = () => {
    try {
      for (const f2 of fs.readdirSync(os.tmpdir())) {
        if (f2.startsWith(`p22-${id}-yt`)) {
          try {
            fs.unlinkSync(path.join(os.tmpdir(), f2));
          } catch {}
        }
      }
    } catch {}
  };
  const ok = await new Promise((resolve) => {
    execFile(
      cmd,
      [
        "-f",
        "bv*[height<=1080][ext=mp4]+ba[ext=m4a]/bv*[height<=1080]+ba/b[height<=1080]/b",
        "--merge-output-format", "mp4",
        "--max-filesize", "200M",
        "--no-playlist",
        "--no-warnings",
        "-o", base,
        url,
      ],
      { timeout: YT_DLP_TIMEOUT_MS, maxBuffer: 4 * 1024 * 1024 },
      (err) => resolve(!err),
    );
  });
  if (!ok) {
    cleanup();
    return null;
  }
  try {
    const files = fs
      .readdirSync(os.tmpdir())
      .filter((f2) => f2.startsWith(`p22-${id}-yt`))
      .map((f2) => path.join(os.tmpdir(), f2))
      .filter((p2) => {
        try {
          return fs.statSync(p2).size > 1024;
        } catch {
          return false;
        }
      })
      .sort((a, b) => fs.statSync(b).size - fs.statSync(a).size);
    if (!files.length) return null;
    const buf = fs.readFileSync(files[0]);
    cleanup();
    return buf.length <= DOWNLOAD_LIMIT ? buf : null;
  } catch {
    cleanup();
    return null;
  }
}

// Descarga cada medio y lo incrusta como data:URI base64 dentro del HTML
// (el visor de WhatsApp no carga URLs remotas por sí mismo; con base64 sí
// reproduce). De paso valida el tipo real por extensión + firma binaria +
// content-type. Si algo falla, deja la URL directa como respaldo.
async function embedMedia(items = []) {
  // 1) Descarga + detección del tipo real (en paralelo)
  await Promise.all(
    items.map(async (item) => {
      // Videos: primero yt-dlp (hasta 1080p, cualquier sitio soportado);
      // si no está disponible o falla, descarga directa del archivo.
      if (item.type === "video") {
        const ytd = await tryYtDlp(item.url).catch(() => null);
        if (ytd?.length) {
          item.viaYtDlp = true;
          item.ct = "video/mp4";
          item.htmlPage = false;
          item.subtitle = `VIDEO • ${item.host || "URL"} • ✓`;
          item.raw = ytd;
          return;
        }
      }

      const dl = await downloadMedia(item.url).catch(() => ({ ok: false }));

      if (!dl.ok) {
        item.httpOk = false;
        item.embedded = "fail";
        return;
      }

      item.httpOk = true;
      if (dl.tooBig) {
        item.embedded = "big";
        return;
      }

      item.ct = dl.contentType || "";
      const ct = item.ct.toLowerCase();
      item.htmlPage = /text\/html|application\/xhtml/.test(ct);

      if (!item.hinted) {
        item.type =
          extType(item.url) ||
          typeFromBytes(dl.buffer) ||
          typeFromContentType(dl.contentType) ||
          item.type;
      }
      item.subtitle = `${item.type.toUpperCase()} • ${item.host || "URL"}${item.htmlPage ? "" : " • ✓"}`;

      if (item.htmlPage || !dl.buffer?.length) {
        item.embedded = "fail";
        return;
      }

      item.raw = dl.buffer;
    }),
  );

  // 2) Compresión secuencial (CPU) solo para lo que excede el límite directo,
  //    con tope de tiempo para no colgar el comando. El objetivo por archivo
  //    se reparte según cuántos medios haya (1 solo = máxima calidad).
  const deadline = Date.now() + 90_000;
  // Objetivo por archivo en bytes CRUDOS (el dataUri cuesta x1.332 extra):
  // con 1 solo video usa todo el presupuesto HQ; con varios, se reparte.
  const perItemTarget = Math.min(
    EMBED_TARGET_HQ,
    Math.floor((EMBED_TOTAL_BUDGET * 0.95) / items.length),
  );
  for (const item of items) {
    if (!item.raw) continue;
    const limit = item.type === "image" ? IMAGE_EMBED_LIMIT : DIRECT_EMBED_LIMIT;
    if (item.raw.length <= limit) continue;
    if (Date.now() > deadline) {
      item.embedded = "big";
      item.raw = undefined;
      continue;
    }
    const compressed = await compressMedia(item.raw, item.type, perItemTarget).catch(() => null);
    if (compressed && compressed.length < item.raw.length) {
      item.rawOriginal = item.raw.length;
      item.__orig = item.raw; // guardado para el plan B (no viaja en el payload)
      item.raw = compressed;
      item.compressed = true;
    }
    // Los comprimidos se miden contra el techo de compresión, no el límite directo
    if (item.raw.length > (item.compressed ? COMPRESS_HARD_CAP : limit)) {
      item.embedded = "big";
      item.raw = undefined;
    }
  }

  // 3) Construir el data:URI de cada medio
  for (const item of items) {
    if (!item.raw) {
      if (!item.embedded) item.embedded = item.httpOk === false ? "fail" : "big";
      continue;
    }
    item.dataUri = dataUriFor(item, item.raw);
    item.embedded = true;
    item.raw = undefined; // no incrustar el buffer crudo en el payload
  }

  // 4) Presupuesto total: EMBED_TOTAL_BUDGET está en bytes crudos; el dataUri
  //    en base64 cuesta x1.332, con margen para el redondeo del codificador.
  let used = 0;
  const totalBudgetBytes = Math.floor(EMBED_TOTAL_BUDGET * 1.45);
  for (const item of items) {
    if (!item.dataUri) continue;
    const size = Buffer.byteLength(item.dataUri);
    if (used + size > totalBudgetBytes) {
      item.embedded = "big";
      delete item.dataUri;
      continue;
    }
    used += size;
  }
  return used;
}

function hostOf(url = "") {
  try {
    return new URL(url).hostname;
  } catch {
    return "";
  }
}

function fileNameOf(url = "") {
  try {
    const parsed = new URL(url);
    const last = decodeURIComponent(parsed.pathname.split("/").filter(Boolean).pop() || "");
    return last || parsed.hostname || "media-url";
  } catch {
    return "media-url";
  }
}

function cleanTitle(value = "") {
  return String(value || "")
    .replace(URL_REGEX, "")
    .replace(/^(audio|aud|musica|música|mp3|video|vid|mp4|imagen|image|img|foto|picture)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 90);
}

function safeScriptJson(value) {
  return JSON.stringify(value, (key, val) =>
    key.startsWith("__") ? undefined : val,
  )
    .replace(/</g, "\\u003c")
    .replace(/>/g, "\\u003e")
    .replace(/&/g, "\\u0026")
    .replace(/\u2028/g, "\\u2028")
    .replace(/\u2029/g, "\\u2029");
}

function buildItems(urls = [], text = "") {
  const hint = getTypeHint(text);
  const customTitle = cleanTitle(text);

  return urls.map((url, index) => {
    const type = guessMediaType(url, hint);
    const host = hostOf(url);
    return {
      url,
      type,
      hinted: Boolean(hint),
      title: customTitle || fileNameOf(url),
      subtitle: `${type.toUpperCase()} • ${host || "URL"}`,
      host,
      number: index + 1,
    };
  });
}

