(function buildBars(){var hs=[46,30,54,38,26,50,34,58,42,28,52,36,24,48,32,56,40,26,50,34,44,30];for(var i=0;i<hs.length;i++){var b=document.createElement('span');b.className='bar';b.style.height=hs[i]+'px';b.style.animationDelay=-(i*0.09)+'s';b.style.animationDuration=(0.7+(i%5)*0.13)+'s';var h=(185+i*9)%360;b.style.background='linear-gradient(180deg,hsl('+h+' 95% 68%),hsl('+((h+45)%360)+' 90% 60%))';bars.appendChild(b)}})();
