vid.addEventListener('play',function(){playing=true;syncUI()});vid.addEventListener('pause',function(){playing=false;syncUI()});aud.addEventListener('play',function(){playing=true;syncUI()});aud.addEventListener('pause',function(){playing=false;syncUI()});vid.addEventListener('error',function(){var it=active();if(!it||it.type!=='video')return;vid.setAttribute('controls','');hint.textContent='⚠️ El video no cargó en el visor. Usa los controles del video o ↗ ABRIR URL.'});aud.addEventListener('error',function(){var it=active();if(!it||it.type==='video')return;hint.textContent='⚠️ El audio no cargó. Usa ↗ ABRIR URL.'});vid.addEventListener('canplay',function(){var it=active();if(it&&it.type==='video')hint.textContent='Video listo.'});
